import { useId } from 'react'

export function EmailField({ label }: { label: string }) {
  const id = useId()
  return (
    <div>
      <label htmlFor={id}>{label}</label>
      <input id={id} type="email" />
    </div>
  )
}

import { useId } from 'react'

export function EmailField({ label, hint }: { label: string; hint: string }) {
  const id = useId()
  const hintId = `${id}-hint`
  return (
    <div>
      <label htmlFor={id}>{label}</label>
      <input id={id} type="email" aria-describedby={hintId} />
      <p id={hintId}>{hint}</p>
    </div>
  )
}
